        zh: CHINESE_WINDOWS_TRAY_MENU_COPY,
        'zh-Hant': TRADITIONAL_CHINESE_WINDOWS_TRAY_MENU_COPY,
        ja: JAPANESE_WINDOWS_TRAY_MENU_COPY
